(() => {
  'use strict';
  const A=window.App, E=A.esc, I=A.icon, S=()=>A.state;
  const nav=[['inicio','home','Início'],['capturar','capture','Capturar'],['conhecimento','book','Conhecimento'],['tarefas','tasks','Tarefas'],['calendario','calendar','Calendário'],['projetos','folder','Projetos'],['habitos','habit','Hábitos'],['financeiro','wallet','Financeiro'],['cofre','lock','Cofre']];
  const names=Object.fromEntries([...nav,['configuracoes','settings','Configurações'],['integracoes','link','Integrações'],['atividade','activity','Atividade'],['onboarding','user','Seu primeiro passo']].map(([key,,label])=>[key,label]));
  const subtitles={inicio:'O que importa hoje, em um só lugar.',capturar:'Tire da cabeça. Organize quando fizer sentido.',conhecimento:'Guarde ideias. Construa conexões.',tarefas:'Menos pendências na cabeça. Mais clareza para agir.',calendario:'Encontre espaço para o que importa.',projetos:'Dê contexto ao que você quer realizar.',habitos:'Pequenos passos, todos os dias.',financeiro:'Entenda seu dinheiro e planeje com calma.',cofre:'Suas informações reservadas, em um lugar só.',configuracoes:'Um Segundo Cérebro do seu jeito.',integracoes:'Conecte o seu contexto.',atividade:'Acompanhe o que mudou no seu espaço.'};
  const statusLabels={todo:'A fazer',doing:'Em andamento',done:'Concluída',archived:'Arquivada'};
  const priorityLabels={low:'Baixa',medium:'Média',high:'Alta',urgent:'Urgente'};
  const projectName=id=>S().projects.find(p=>p.id===id)?.title||'Sem projeto';
  const projectOptions=(id='')=>`<option value="">Sem projeto</option>`+S().projects.map(p=>`<option value="${E(p.id)}" ${id===p.id?'selected':''}>${E(p.title)}</option>`).join('');
  const selectOptions=(obj,value)=>Object.entries(obj).map(([v,l])=>`<option value="${v}" ${value===v?'selected':''}>${l}</option>`).join('');
  const badge=(text,color='')=>`<span class="pill ${color}">${E(text)}</span>`;
  const empty=(title,text,button='')=>`<div class="empty">${I('inbox',32)}<h3>${E(title)}</h3><p>${E(text)}</p>${button}</div>`;
  const link=(route,label)=>`<a class="text-link" href="#/${route}">${E(label)}${I('arrow-up-right',16)}</a>`;
  const taskRow=t=>`<div class="task-row ${t.status==='done'?'completed':''}"><button class="check-button ${t.status==='done'?'checked':''}" data-action="toggle-task" data-id="${E(t.id)}" aria-label="${t.status==='done'?'Reabrir':'Concluir'} ${E(t.title)}" aria-pressed="${t.status==='done'}">${t.status==='done'?I('check',15):''}</button><button class="task-copy" data-action="open-task" data-id="${E(t.id)}"><strong>${E(t.title)}</strong><span>${E(projectName(t.project))} <span aria-hidden="true">·</span> ${E(t.category||'Pessoal')}</span></button><span class="task-due ${t.due<A.TODAY&&t.status!=='done'?'overdue':''}">${t.status==='done'?I('check',15):t.due===A.TODAY?'Hoje':A.dateLabel(t.due)}</span></div>`;
  const todayEvents=()=>S().events.filter(e=>S().calendarSources[e.source]&&(e.date===A.TODAY||(e.allDay&&e.date<=A.TODAY&&e.endDate>A.TODAY))).sort((a,b)=>(a.start||'').localeCompare(b.start||''));
  const sourceName={work:'Trabalho',personal:'Pessoal',study:'Estudos'};
  const sourceColor={work:'work',personal:'personal',study:'study'};
  function brand(){return `<svg class="brand-mark" width="36" height="36" viewBox="0 0 64 64" fill="none" aria-hidden="true"><rect width="64" height="64" rx="16" fill="currentColor"/><path d="M18.5 20C18.5 15.858 21.858 12.5 26 12.5H35C41.627 12.5 47 17.873 47 24.5C47 28.253 45.245 31.791 42.255 34.056L21.5 49.5H47" stroke="var(--sidebar)" stroke-width="5.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="18.5" cy="20" r="3" fill="currentColor" stroke="var(--sidebar)" stroke-width="1.5"/><circle cx="47" cy="49.5" r="3" fill="currentColor" stroke="var(--sidebar)" stroke-width="1.5"/></svg>`;}
  A.brand=brand;
  A.render=function(){
    if(this.ui.route==='onboarding')return this.onboarding.render();
    const route=this.ui.route, page=this.routes[route];
    const routeKey=route+'/'+(this.ui.id||''),active=document.activeElement;
    const focusData=this._renderedRouteKey===routeKey&&active?.dataset?.action&&active.closest?.('#app')?Object.entries(active.dataset):null;
    const matchesFocus=element=>element.tagName===active?.tagName&&focusData?.every(([key,value])=>element.dataset[key]===value);
    const focusIndex=focusData?[...document.querySelectorAll('#app [data-action]')].filter(matchesFocus).indexOf(active):-1;
    const counts=S().captures.filter(c=>!c.converted).length;
    document.title=`Segundo Cérebro · ${names[route]||'Início'}`;
    const collapsed=this.ui.sidebarCollapsed;
    const navItem=([key,icon,label])=>`<a class="nav-link ${route===key?'active':''}" href="#/${key}" aria-label="${label}" data-tooltip="${label}" ${route===key?'aria-current="page"':''}>${I(icon)}<span class="nav-label">${label}</span>${key==='capturar'&&counts?`<span class="nav-count" aria-hidden="true">${counts}</span>`:''}</a>`;
    document.querySelector('#app').innerHTML=`
      <div class="app-shell ${collapsed?'is-collapsed':''} ${this.ui.mobileNav?'nav-open':''}" data-route="${route}">
        <button class="nav-scrim" data-action="toggle-menu" tabindex="-1" aria-label="Fechar navegação"></button>
        <aside class="sidebar" id="main-sidebar" aria-label="Navegação principal">
          <div class="brand-row"><a class="brand" href="#/inicio" aria-label="Segundo Cérebro, início" data-tooltip="Segundo Cérebro">${brand()}<span>segundo<br><b>cérebro</b><span class="brand-dot">.</span></span></a><button class="icon-button sidebar-close" data-action="toggle-menu" aria-label="Fechar navegação">${I('x')}</button></div>
          <div class="sidebar-scroll">
            <button class="sidebar-search" data-action="search" aria-label="Buscar no Segundo Cérebro" data-tooltip="Buscar · Ctrl K">${I('search',19)}<span>Buscar</span><kbd>Ctrl K</kbd></button>
            <nav aria-label="Áreas do Segundo Cérebro">
              <div class="nav-group"><span class="nav-group-label">Meu dia</span>${[nav[0],nav[1],nav[3],nav[4]].map(navItem).join('')}</div>
              <div class="nav-group"><span class="nav-group-label">Meu contexto</span>${[nav[2],nav[5]].map(navItem).join('')}</div>
              <div class="nav-group"><span class="nav-group-label">Vida pessoal</span>${nav.slice(6).map(navItem).join('')}</div>
            </nav>
          </div>
          <div class="sidebar-bottom">${[['integracoes','link','Integrações'],['configuracoes','settings','Configurações']].map(navItem).join('')}
            <a class="profile" href="#/configuracoes" aria-label="Perfil de ${E(S().settings.name||'Kauan')}" data-tooltip="Meu perfil"><span class="avatar">${E((S().settings.name||'Kauan').slice(0,1).toUpperCase())}</span><span><b>${E(S().settings.name||'Kauan')}</b><small>Meu espaço pessoal</small></span>${I('chevron-down',16)}</a>
          </div>
        </aside>
        <div class="workspace">
          <header class="topbar"><div class="breadcrumb">
            <button class="icon-button sidebar-toggle" data-action="toggle-sidebar" aria-controls="main-sidebar" aria-expanded="${!collapsed}" aria-label="${collapsed?'Expandir':'Recolher'} menu lateral" title="${collapsed?'Expandir':'Recolher'} menu lateral">${I('panel-left')}</button>
            <button class="icon-button mobile-menu" data-action="toggle-menu" aria-controls="main-sidebar" aria-expanded="${this.ui.mobileNav}" aria-label="Abrir navegação">${I('menu')}</button>
            <span>Meu espaço</span>${I('chevron-right',14)}<strong>${names[route]||'Início'}</strong>
          </div><div class="top-actions"><span class="demo-badge"><span></span>Demonstração</span><button class="icon-button" data-action="toggle-theme" aria-label="Alternar para modo ${document.documentElement.dataset.theme==='dark'?'claro':'escuro'}" title="Alternar tema">${I(document.documentElement.dataset.theme==='dark'?'sun':'moon')}</button><a class="icon-button" href="#/atividade" aria-label="Ver atividade" title="Atividade">${I('activity')}</a><button class="button primary capture-global" data-action="quick-capture">${I('plus',17)}<span>Capturar</span></button></div></header>
          <main id="main" tabindex="-1"><div class="page-heading"><div><h1>${route==='inicio'?`Bom dia, ${E(S().settings.name||'Kauan')}.`:names[route]||'Página não encontrada'}</h1><p>${subtitles[route]||'Volte para seu panorama.'}</p></div>${route==='inicio'?`<div class="date-chip">${I('calendar',18)}<span>Sábado, <strong>17 de outubro</strong></span></div>`:''}</div>${this.storageError?'<div class="notice" role="status">Armazenamento indisponível. As alterações ficam apenas nesta sessão.</div>':''}<div class="page-content">${route==='inicio'?this.onboarding.banner():''}${page?page():empty('Página não encontrada','Escolha um destino no menu.',`<a class="button" href="#/inicio">Voltar ao Início</a>`) }${route==='configuracoes'?this.onboarding.settings():''}</div><footer class="app-footer"><span>Um lugar para pensar com clareza.</span><span>Dados fictícios · 17 out 2026 · Salvo neste navegador</span></footer></main>
        </div>
        <nav class="mobile-bottom" aria-label="Navegação rápida">${[['inicio','home','Início'],['tarefas','tasks','Tarefas'],['capturar','plus','Capturar'],['calendario','calendar','Agenda']].map(([key,icon,label])=>`<a href="#/${key}" class="${route===key?'active':''}" ${route===key?'aria-current="page"':''}>${I(icon)}<span>${label}</span></a>`).join('')}<button data-action="toggle-menu" aria-controls="main-sidebar" aria-expanded="${this.ui.mobileNav}">${I('menu')}<span>Mais</span></button></nav>
      </div>`;

    this.syncShell?.();
    this._renderedRouteKey=routeKey;
    if(focusData){const candidates=[...document.querySelectorAll('#app [data-action]')].filter(matchesFocus);const target=candidates[Math.min(Math.max(focusIndex,0),candidates.length-1)];if(target&&!target.disabled)target.focus({preventScroll:true});}
  };
  A.routes.inicio=()=>{
    const tasks=S().tasks.filter(t=>!t.deleted&&t.status!=='archived'&&t.due===A.TODAY),open=tasks.filter(t=>t.status!=='done'),focus=open[0],done=tasks.filter(t=>t.status==='done').length;
    const habits=S().habits.filter(h=>A.lifeHabitEligible?A.lifeHabitEligible(h):!h.paused&&!h.archived),habitDone=habits.filter(h=>h.checked.includes(A.TODAY)).length;
    const fin=A.lifeFinanceSummary?.()||{cash:0,income:0,expense:0,cardDebt:0};
    return `<div class="home-top"><section class="focus-panel"><h2>${focus?E(focus.title):'Você abriu espaço no seu dia.'}</h2><p>${focus?'Um passo de cada vez. Comece pelo que faz diferença agora.':'As tarefas de hoje estão concluídas. Que tal uma pausa?'}</p><div class="focus-context">${I('target',17)}<span>${focus?`Em foco · ${focus.estimate||25} min de dedicação`:'Tarefas de hoje concluídas'}</span></div><div class="focus-bottom">${focus?`<button class="button focus-button" data-action="toggle-task" data-id="${E(focus.id)}">${I('check',18)}Concluir tarefa</button><button class="focus-detail" data-action="open-task" data-id="${E(focus.id)}">Ver detalhes ${I('arrow-up-right',16)}</button>`:`<a class="button focus-button" href="#/tarefas">Ver minhas tarefas ${I('arrow-right',18)}</a>`}</div></section><section class="day-summary"><h2>Seu ritmo hoje</h2><div class="day-number"><strong>${done}<span> / ${tasks.length}</span></strong><span>tarefas concluídas</span></div><div class="segmented-progress" aria-label="${done} de ${tasks.length} tarefas concluídas">${tasks.map((t,i)=>`<span class="${i<done?'filled':''}"></span>`).join('')}</div><div class="day-meta"><span>${I('habit',18)} ${habitDone} de ${habits.length} hábitos</span><a href="#/atividade" aria-label="Ver atividade do dia">${I('arrow-up-right',18)}</a></div></section></div>
    <div class="home-main"><section class="panel task-panel"><div class="section-head"><h2>Tarefas de hoje <span class="count">${open.length}</span></h2>${link('tarefas','Ver todas')}</div>${tasks.length?tasks.map(taskRow).join(''):empty('Seu dia está livre','Adicione sua próxima ação quando precisar.')}<button class="inline-add" data-action="new-task">${I('plus',17)} Adicionar tarefa</button></section><section class="panel agenda-panel"><div class="section-head"><h2>Na sua agenda</h2>${link('calendario','Abrir')}</div><div class="week-strip">${['S','T','Q','Q','S','S','D'].map((d,i)=>`<a href="#/calendario" data-action="home-calendar-date" data-date="2026-10-${12+i}" class="${i===5?'today':''}"><span>${d}</span><strong>${12+i}</strong><i></i></a>`).join('')}</div><div class="agenda-list">${todayEvents().slice(0,4).map(e=>`<button class="agenda-item" data-action="home-event" data-id="${E(e.id)}"><time>${e.allDay?'Dia todo':e.start}</time><span class="event-dot ${sourceColor[e.source]}"></span><span><strong>${E(e.title)}</strong><small>${E(sourceName[e.source])} ${!e.allDay?`· ${e.start}–${e.end}`:''}</small></span>${I('chevron-right',15)}</button>`).join('')||'<p class="muted">Nenhum compromisso das fontes selecionadas.</p>'}</div></section></div>
    <div class="home-bottom"><section class="panel"><div class="section-head"><h2>Pequenos hábitos</h2>${link('habitos','Ver rotina')}</div>${habits.slice(0,3).map(h=>`<div class="habit-home-row"><span class="habit-symbol">${I(h.id==='h1'?'book':h.id==='h2'?'activity':'sun',19)}</span><span><strong>${E(h.title)}</strong><small>${E(A.lifeHabitSchedule?A.lifeHabitSchedule(h):h.goal)}</small></span><button class="check-button ${h.checked.includes(A.TODAY)?'checked':''}" data-action="home-habit" data-id="${E(h.id)}" aria-label="${h.checked.includes(A.TODAY)?'Desmarcar':'Marcar'} ${E(h.title)}" aria-pressed="${h.checked.includes(A.TODAY)}">${h.checked.includes(A.TODAY)?I('check',15):''}</button></div>`).join('')}</section><section class="panel finance-home"><div class="section-head"><h2>Seu dinheiro</h2>${link('financeiro','Ver resumo')}</div><p class="muted">Saldo em contas</p><strong class="money-large">${S().settings.hideAmounts?'R$ •••••':A.money(fin.cash)}</strong><div class="finance-mini"><span>Entradas <b>${S().settings.hideAmounts?'•••':A.money(fin.income)}</b></span><span>Despesas <b>${S().settings.hideAmounts?'•••':A.money(fin.expense)}</b></span></div><button class="inline-add" data-action="home-transaction">${I('plus',17)} Registrar gasto</button></section><section class="inbox-home"><span class="inbox-visual">${I('inbox',30)}</span><h2>Ideias pedem espaço.</h2><p>Você tem <strong>${S().captures.filter(c=>!c.converted).length} capturas</strong> esperando por um próximo passo.</p><a class="text-link" href="#/capturar">Organizar a entrada ${I('arrow-right',18)}</a></section></div>
    <section class="recent-notes"><div class="section-head"><h2>Continue de onde parou</h2>${link('conhecimento','Todo o conhecimento')}</div><div class="notes-strip">${S().notes.filter(n=>!n.deleted).slice(0,3).map(n=>`<a href="#/conhecimento/${n.id}" class="note-preview">${I('file-text',21)}<span><strong>${E(n.title)}</strong><small>${E(n.notebook)} · ${A.dateLabel(n.updated)}</small></span>${I('arrow-up-right',17)}</a>`).join('')}</div></section>`;
  };
  A.routes.capturar=()=>{
    const mode=A.ui.captureFilter||'inbox',items=S().captures.filter(c=>mode==='all'||(mode==='inbox'?!c.converted:!!c.converted));
    return `<div class="capture-layout"><section class="capture-compose panel"><div class="section-head"><h2>O que está na sua cabeça?</h2>${I('capture')}</div><form data-form="capture"><label class="sr-only" for="capture-title">Título da captura</label><input id="capture-title" name="title" class="capture-title" placeholder="Uma ideia, uma tarefa, um lembrete…" maxlength="160" required><label class="sr-only" for="capture-body">Detalhes da captura</label><textarea id="capture-body" name="body" placeholder="Escreva livremente. A organização vem depois." rows="5"></textarea><div class="compose-bottom"><label class="select-inline"><span class="sr-only">Tipo</span><select name="type"><option value="idea">Ideia</option><option value="task">Tarefa</option><option value="note">Nota</option><option value="reminder">Lembrete</option></select></label><button class="button primary" type="submit">${I('plus',17)} Salvar captura</button></div></form></section><aside class="capture-tip"><div class="tip-lines" aria-hidden="true"><span></span><span></span><span></span></div><h2>Primeiro, tire da cabeça.</h2><p>Você não precisa decidir o lugar de uma ideia para começar a guardá-la.</p><p class="small muted">Depois, transforme em tarefa ou leve para um caderno.</p></aside></div><div class="section-head capture-list-head"><div class="tabs">${[['inbox','Caixa de entrada'],['organized','Organizadas'],['all','Todas']].map(([key,label])=>`<button class="tab ${mode===key?'active':''}" data-action="capture-filter" data-value="${key}">${label}${key==='inbox'?` <span class="count">${S().captures.filter(c=>!c.converted).length}</span>`:''}</button>`).join('')}</div><span class="muted small">${items.length} ${items.length===1?'captura':'capturas'}</span></div><div class="capture-list">${items.map(c=>`<article class="capture-item"><span class="capture-type-icon">${I(c.type==='task'?'tasks':c.type==='note'?'file-text':'capture',21)}</span><div class="capture-content"><div class="row"><h3>${E(c.title)}</h3>${badge(c.converted?'Organizada':({idea:'Ideia',task:'Tarefa',note:'Nota',reminder:'Lembrete'}[c.type]))}</div><p>${E(c.body)}</p><small>${A.dateLabel(c.created)}${c.converted?' · Origem preservada':''}</small></div><div class="capture-actions">${c.converted?`<a class="button" href="#/${c.taskId?'tarefas/'+c.taskId:'conhecimento/'+c.noteId}">Abrir ${c.taskId?'tarefa':'nota'}${I('arrow-up-right',16)}</a>`:`<button class="button" data-action="convert-capture" data-id="${c.id}">${I('tasks',17)}Virar tarefa</button><button class="icon-button" data-action="promote-capture" data-id="${c.id}" aria-label="Organizar ${E(c.title)} em Conhecimento" title="Organizar em Conhecimento">${I('book',19)}</button><button class="icon-button" data-action="edit-capture" data-id="${c.id}" aria-label="Editar ${E(c.title)}">${I('edit',17)}</button>`}</div></article>`).join('')||empty(mode==='inbox'?'Tudo ganhou seu lugar.':'Nenhuma captura aqui.',mode==='inbox'?'Sua caixa de entrada está organizada. A próxima ideia pode vir.':'As capturas organizadas aparecerão aqui.')}</div>`;
  };
  A.routes.tarefas=()=>{
    let tasks=S().tasks;const filter=A.ui.taskFilter||'all',q=(A.ui.taskQuery||'').toLocaleLowerCase('pt-BR');
    tasks=tasks.filter(t=>filter==='trash'?t.deleted:!t.deleted&&(filter==='archived'?t.status==='archived':t.status!=='archived'));
    if(filter==='today')tasks=tasks.filter(t=>t.due===A.TODAY);if(filter==='done')tasks=tasks.filter(t=>t.status==='done');if(filter==='open')tasks=tasks.filter(t=>t.status!=='done');
    if(q)tasks=tasks.filter(t=>(t.title+' '+projectName(t.project)).toLocaleLowerCase('pt-BR').includes(q));
    if(A.ui.taskProject)tasks=tasks.filter(t=>t.project===A.ui.taskProject);
    const sorted=tasks.slice().sort((a,b)=>A.ui.taskSort==='priority'?(['urgent','high','medium','low'].indexOf(a.priority)-['urgent','high','medium','low'].indexOf(b.priority)):(a.due||'9999').localeCompare(b.due||'9999'));
    return `<div class="toolbar"><div class="tabs">${[['all','Todas'],['today','Hoje'],['open','Abertas'],['done','Concluídas'],['archived','Arquivo'],['trash','Lixeira']].map(([v,l])=>`<button class="tab ${filter===v?'active':''}" data-action="task-filter" data-value="${v}">${l}</button>`).join('')}</div><button class="button primary" data-action="new-task">${I('plus',17)}Nova tarefa</button></div><div class="filter-bar"><label class="search-field">${I('search',17)}<input type="search" data-input="task-search" value="${E(A.ui.taskQuery||'')}" placeholder="Buscar tarefas…" aria-label="Buscar tarefas"></label><label class="select-inline"><span class="sr-only">Filtrar por projeto</span><select data-change="task-project">${`<option value="">Todos os projetos</option>`+S().projects.map(p=>`<option value="${p.id}" ${A.ui.taskProject===p.id?'selected':''}>${E(p.title)}</option>`).join('')}</select></label><label class="select-inline"><span class="sr-only">Ordenar tarefas</span><select data-change="task-sort"><option value="date">Por prazo</option><option value="priority" ${A.ui.taskSort==='priority'?'selected':''}>Por prioridade</option></select></label><span class="muted small">${sorted.length} tarefas</span></div><section class="panel task-table"><div class="task-table-head"><span>Tarefa</span><span>Projeto</span><span>Prioridade</span><span>Prazo</span><span>Estado</span></div>${sorted.map(t=>`<div class="task-table-row"><div class="task-name-cell"><button class="check-button ${t.status==='done'?'checked':''}" data-action="${t.deleted?'restore-task':'toggle-task'}" data-id="${t.id}" aria-label="${t.deleted?'Restaurar':t.status==='done'?'Reabrir':'Concluir'} ${E(t.title)}">${I(t.deleted?'refresh':t.status==='done'?'check':'',15)}</button><button class="task-copy" data-action="open-task" data-id="${t.id}"><strong class="${t.status==='done'?'strike':''}">${E(t.title)}</strong><span>${E(t.category)} ${t.origin?'· Captura de origem':''}</span></button></div><span class="project-cell">${E(projectName(t.project))}</span><span>${badge(priorityLabels[t.priority],t.priority==='high'||t.priority==='urgent'?'warm':'')}</span><span class="small">${t.due===A.TODAY?'Hoje':A.dateLabel(t.due)}</span><span>${badge(t.deleted?'Na lixeira':statusLabels[t.status],t.status==='doing'?'blue':t.status==='done'?'green':'')}</span></div>`).join('')||empty(q?'Nenhuma tarefa encontrada':'Nada pendente por aqui',q?'Tente outra palavra ou remova os filtros.':'Crie uma tarefa para dar o próximo passo.',`<button class="button" data-action="new-task">Criar tarefa</button>`)}</section>`;
  };
  A.taskDialog=function(id,defaults={}){
    const t=S().tasks.find(t=>t.id===id)||{title:'',description:'',category:'Pessoal',project:'',status:'todo',priority:'medium',due:A.TODAY,estimate:25,...defaults};
    A.openDialog(id?'Detalhes da tarefa':'Nova tarefa',`<form data-form="task"><input name="id" type="hidden" value="${E(id||'')}"><input name="origin" type="hidden" value="${E(t.origin||'')}"><input name="relatedEvent" type="hidden" value="${E(t.relatedEvent||'')}"><label class="field">O que precisa ser feito?<input name="title" value="${E(t.title)}" required maxlength="180" autofocus ${t.deleted?'readonly':''}></label><label class="field">Descrição<textarea name="description" rows="3" placeholder="Adicione o contexto necessário…">${E(t.description)}</textarea></label><div class="form-grid"><label class="field">Projeto<select name="project">${projectOptions(t.project)}</select></label><label class="field">Categoria<select name="category">${selectOptions({Trabalho:'Trabalho',Estudos:'Estudos',Pessoal:'Pessoal'},t.category)}</select></label><label class="field">Estado<select name="status">${selectOptions(statusLabels,t.status)}</select></label><label class="field">Prioridade<select name="priority">${selectOptions(priorityLabels,t.priority)}</select></label><label class="field">Prazo<input name="due" type="date" value="${E(t.due)}"></label><label class="field">Estimativa (minutos)<input name="estimate" type="number" min="1" max="1440" value="${t.estimate||25}"></label></div><label class="field">Nota relacionada<select name="noteId"><option value="">Sem nota</option>${S().notes.filter(n=>!n.deleted).map(n=>`<option value="${n.id}" ${t.noteId===n.id?'selected':''}>${E(n.title)}</option>`).join('')}</select></label>${t.noteId?`<div class="row"><button type="button" class="text-link" data-action="task-related-note">${I('file-text',17)}Abrir nota relacionada ${I('arrow-up-right',15)}</button></div>`:''}${t.origin?`<div class="notice">${I('link',18)}<span>Origem: <button type="button" class="text-link" data-action="view-origin" data-id="${E(t.origin)}">${E(S().captures.find(c=>c.id===t.origin)?.title||'Captura')}</button></span></div>`:''}${t.relatedEvent?`<div class="notice">${I('calendar',18)}<button type="button" class="text-link" data-action="task-related-event" data-id="${E(t.relatedEvent)}">${E(S().events.find(e=>e.id===t.relatedEvent)?.title||'Abrir compromisso')} ${I('arrow-up-right',15)}</button></div>`:''}<div class="dialog-actions">${id?`<button type="button" class="button ${t.deleted?'':'danger-text'}" data-action="${t.deleted?'restore-task':'delete-task'}" data-id="${id}">${I(t.deleted?'refresh':'trash',17)}${t.deleted?'Restaurar':'Excluir'}</button>`:''}<span class="spacer"></span><button type="button" class="button" data-action="close-dialog">Cancelar</button>${!t.deleted?'<button type="submit" class="button primary">Salvar tarefa</button>':''}</div></form>`);
  };
  function renderNoteText(note){let body=E(note.body);body=body.replace(/\[\[([^\]]+)\]\]/g,(all,title)=>{const n=S().notes.find(n=>E(n.title)===title&&!n.deleted);return n?`<a href="#/conhecimento/${n.id}" class="wiki-link">${title}</a>`:`<button class="wiki-link" data-action="unresolved-note" data-title="${title}">${title} ${I('plus',12)}</button>`;});return body.split('\n\n').map(p=>`<p>${p.replace(/\n/g,'<br>')}</p>`).join('');}
  A.routes.conhecimento=()=>{
    const notes=S().notes.filter(n=>!n.deleted),selected=notes.find(n=>n.id===A.ui.id),filter=A.ui.noteFilter||'Todos',filtered=notes.filter(n=>filter==='Todos'||n.notebook===filter);
    return `<div class="knowledge-layout"><aside class="notebook-nav"><div class="section-head"><h2>Cadernos</h2><button class="icon-button" data-action="new-notebook" aria-label="Criar caderno">${I('plus',18)}</button></div>${['Todos',...S().notebooks].map(n=>`<button class="notebook-item ${filter===n?'active':''}" data-action="notebook-filter" data-value="${E(n)}">${I(n==='Todos'?'grid':'book',18)}<span>${E(n)}</span><small>${n==='Todos'?notes.length:notes.filter(x=>x.notebook===n).length}</small></button>`).join('')}<div class="notebook-help">${I('link',20)}<p>Ideias conectadas são mais fáceis de reencontrar.</p><small>Use [[nome da página]] para criar uma referência.</small></div></aside><section class="knowledge-main">${selected?`<div class="editor-top"><a class="text-link" href="#/conhecimento">${I('chevron-left',17)}Todas as páginas</a><div><button class="icon-button" data-action="delete-note" data-id="${selected.id}" aria-label="Excluir página">${I('trash',18)}</button><button class="button" data-action="edit-note" data-id="${selected.id}">${I('edit',17)}Editar página</button></div></div><article class="note-document"><div class="note-context">${I('book',17)} ${E(selected.notebook)} <span>·</span> ${A.dateLabel(selected.updated)}</div><h2>${E(selected.title)}</h2><div class="note-prose">${renderNoteText(selected)}</div><div class="note-relations"><h3>${I('link',17)}Relacionado</h3><div class="relation-list">${selected.project?`<a href="#/projetos/${selected.project}">${I('folder',17)}${E(projectName(selected.project))}${I('arrow-up-right',15)}</a>`:''}${S().tasks.filter(t=>!t.deleted&&t.noteId===selected.id).map(t=>`<button data-action="open-task" data-id="${t.id}">${I('tasks',17)}${E(t.title)}${I('arrow-up-right',15)}</button>`).join('')}${selected.relatedEvent?`<button data-action="home-event" data-id="${selected.relatedEvent}">${I('calendar',17)}${E(S().events.find(e=>e.id===selected.relatedEvent)?.title||'Compromisso')}${I('arrow-up-right',15)}</button>`:''}${selected.origin?`<button data-action="view-origin" data-id="${selected.origin}">${I('capture',17)}Captura de origem${I('arrow-up-right',15)}</button>`:''}</div><h3>Mencionada em</h3>${notes.filter(n=>n.id!==selected.id&&n.body.includes('[['+selected.title+']]')).map(n=>`<a class="backlink" href="#/conhecimento/${n.id}">${I('file-text',17)}${E(n.title)}${I('arrow-up-right',15)}</a>`).join('')||'<p class="muted small">As páginas que mencionarem esta nota aparecerão aqui.</p>'}</div></article>`:`<div class="section-head"><h2>${E(filter==='Todos'?'Suas páginas':filter)} <span class="count">${filtered.length}</span></h2><button class="button primary" data-action="new-note">${I('plus',17)}Nova página</button></div><div class="notes-grid">${filtered.map(n=>`<a class="note-card" href="#/conhecimento/${n.id}"><div>${I('file-text',23)}<span>${E(n.notebook)}</span></div><h3>${E(n.title)}</h3><p>${E(n.body.slice(0,150))}</p><footer><span>Atualizada em ${A.dateLabel(n.updated)}</span>${I('arrow-up-right',17)}</footer></a>`).join('')||empty('Seu caderno começa aqui','Registre o primeiro pensamento que merece ser guardado.',`<button class="button" data-action="new-note">Criar página</button>`)}</div>`}</section></div>`;
  };
  A.openNote=id=>{if(S().notes.some(n=>n.id===id&&!n.deleted))return A.go('conhecimento',id);const event=S().events.find(item=>item.noteId===id);if(event)return A.createEventNote(event.id);A.notify('Esta página não está disponível.');A.go('conhecimento');};
  A.noteDialog=(id,defaults={})=>{
    const n=S().notes.find(n=>n.id===id)||{title:'',body:'',notebook:A.ui.noteFilter&&A.ui.noteFilter!=='Todos'?A.ui.noteFilter:'Produto',project:'',...defaults};
    A.openDialog(id?'Editar página':'Nova página',`<form data-form="note"><input type="hidden" name="id" value="${E(id||'')}"><input type="hidden" name="origin" value="${E(n.origin||'')}"><input type="hidden" name="relatedEvent" value="${E(n.relatedEvent||'')}"><label class="field">Título<input name="title" value="${E(n.title)}" required maxlength="180" autofocus></label><div class="form-grid"><label class="field">Caderno<select name="notebook">${S().notebooks.map(b=>`<option ${b===n.notebook?'selected':''}>${E(b)}</option>`).join('')}</select></label><label class="field">Projeto<select name="project">${projectOptions(n.project)}</select></label></div><label class="field">Conteúdo<textarea name="body" rows="12" placeholder="Escreva suas ideias. Use [[nome da página]] para conectar." required>${E(n.body)}</textarea></label><p class="muted small">Conecte ideias com [[nome da página]]. Os vínculos ficam disponíveis após salvar.</p><div class="dialog-actions"><button type="button" class="button" data-action="close-dialog">Cancelar</button><button type="submit" class="button primary">Salvar página</button></div></form>`);
  };
  A.createEventNote=id=>{const e=S().events.find(e=>e.id===id);if(!e)return;if(e.noteId&&S().notes.some(n=>n.id===e.noteId&&!n.deleted))return A.openNote(e.noteId);delete e.noteId;A.noteDialog(null,{title:'Notas · '+e.title,body:'Pauta\n\nDecisões\n\nPróximos passos',notebook:'Produto',project:e.project||'',relatedEvent:id});};
  A.routes.projetos=()=>{
    const p=S().projects.find(p=>p.id===A.ui.id);
    if(p){const tasks=S().tasks.filter(t=>!t.deleted&&t.project===p.id),notes=S().notes.filter(n=>!n.deleted&&n.project===p.id);return `<a class="text-link back-link" href="#/projetos">${I('chevron-left',17)}Todos os projetos</a><section class="project-hero ${p.color}"><div><div class="row">${badge(p.status==='done'?'Concluído':'Em andamento',p.color)}<span class="muted small">Até ${A.dateLabel(p.deadline)}</span></div><h2>${E(p.title)}</h2><p>${E(p.description)}</p></div><button class="button" data-action="edit-project" data-id="${p.id}">${I('edit',17)}Editar projeto</button></section><div class="project-detail-grid"><section class="panel"><div class="section-head"><h2>Tarefas <span class="count">${tasks.length}</span></h2><button class="text-link" data-action="project-task" data-id="${p.id}">${I('plus',16)}Adicionar</button></div>${tasks.map(taskRow).join('')||empty('Qual é o próximo passo?','Adicione uma tarefa a este projeto.')}</section><section class="panel"><div class="section-head"><h2>Conhecimento relacionado</h2></div>${notes.map(n=>`<a href="#/conhecimento/${n.id}" class="note-preview">${I('file-text',19)}<span><strong>${E(n.title)}</strong><small>${E(n.notebook)}</small></span>${I('arrow-up-right',16)}</a>`).join('')||'<p class="muted">As notas deste projeto aparecerão aqui.</p>'}<div class="section-head spaced"><h2>Compromissos</h2></div>${S().events.filter(e=>e.project===p.id&&e.date>=A.TODAY).map(e=>`<button class="project-event" data-action="home-event" data-id="${e.id}">${I('calendar',18)}<span>${E(e.title)}<small>${A.dateLabel(e.date)} · ${e.start||'Dia todo'}</small></span></button>`).join('')||'<p class="muted small">Nenhum compromisso futuro relacionado.</p>'}</section></div>`;}
    return `<div class="toolbar"><p class="muted">${S().projects.filter(p=>p.status!=='done').length} projetos em andamento</p><button class="button primary" data-action="new-project">${I('plus',17)}Novo projeto</button></div><div class="project-grid">${S().projects.map(p=>{const tasks=S().tasks.filter(t=>!t.deleted&&t.status!=='archived'&&t.project===p.id),done=tasks.filter(t=>t.status==='done').length;return `<a class="project-card" href="#/projetos/${p.id}"><div class="project-card-top"><span class="project-symbol ${p.color}">${I('folder',24)}</span>${I('arrow-up-right',20)}</div>${badge(p.status==='done'?'Concluído':'Em andamento',p.color)}<h2>${E(p.title)}</h2><p>${E(p.description)}</p><div class="project-progress-label"><span>${done} de ${tasks.length} tarefas</span><b>${tasks.length?Math.round(done/tasks.length*100):0}%</b></div><progress value="${done}" max="${tasks.length||1}" aria-label="Progresso de ${E(p.title)}"></progress><footer>${I('calendar',15)}Até ${A.dateLabel(p.deadline)}<span>${S().notes.filter(n=>n.project===p.id&&!n.deleted).length} notas</span></footer></a>`;}).join('')}</div>`;
  };
  function projectDialog(id){const p=S().projects.find(p=>p.id===id)||{title:'',description:'',deadline:'2026-10-30',status:'active',color:'blue'};A.openDialog(id?'Editar projeto':'Novo projeto',`<form data-form="project"><input type="hidden" name="id" value="${E(id||'')}"><label class="field">Nome do projeto<input name="title" value="${E(p.title)}" required maxlength="100" autofocus></label><label class="field">O que você quer alcançar?<textarea name="description" rows="3" required>${E(p.description)}</textarea></label><div class="form-grid"><label class="field">Prazo<input type="date" name="deadline" value="${E(p.deadline)}"></label><label class="field">Estado<select name="status"><option value="active">Em andamento</option><option value="done" ${p.status==='done'?'selected':''}>Concluído</option></select></label></div><div class="dialog-actions"><button class="button" type="button" data-action="close-dialog">Cancelar</button><button class="button primary" type="submit">Salvar projeto</button></div></form>`);}
  A.routes.atividade=()=>`<section class="panel activity-panel"><div class="section-head"><h2>Movimentos do seu espaço</h2><span class="pill">Neste navegador</span></div>${S().activity.map(a=>`<div class="activity-row"><span class="activity-icon">${I('activity',18)}</span><div><h3>${E(a.title)}</h3>${a.detail?`<p>${E(a.detail)}</p>`:''}<small>${new Date(a.time).toLocaleString('pt-BR',{timeZone:'America/Fortaleza',day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'})} · Protótipo local</small></div></div>`).join('')}</section>`;
  function quickCapture(id){const c=S().captures.find(c=>c.id===id)||{title:'',body:'',type:'idea'};A.openDialog(id?'Editar captura':'Capture antes que a ideia passe',`<form data-form="capture"><input name="id" type="hidden" value="${E(id||'')}"><label class="field">O que está na sua cabeça?<input name="title" value="${E(c.title)}" placeholder="Uma ideia, uma tarefa, um lembrete…" required maxlength="160" autofocus></label><label class="field">Detalhes<textarea name="body" rows="5" placeholder="Organize depois. Agora, só escreva.">${E(c.body)}</textarea></label><label class="field">Tipo<select name="type">${selectOptions({idea:'Ideia',task:'Tarefa',note:'Nota',reminder:'Lembrete'},c.type)}</select></label><div class="dialog-actions"><button class="button" type="button" data-action="close-dialog">Cancelar</button><button class="button primary" type="submit">Salvar captura</button></div></form>`);}
  A.forms.capture=(data,form)=>{const title=String(data.get('title')||'').trim();if(!title)return;const id=data.get('id');const c=S().captures.find(c=>c.id===id);if(c?.converted)return A.notify('Esta captura já foi organizada. Abra o registro de destino.');const values={title,body:String(data.get('body')||'').trim(),type:data.get('type')||'idea'};if(c)Object.assign(c,values);else S().captures.unshift({id:A.uid('c'),...values,created:A.TODAY});form.reset();A.closeDialog();A.persist(c?'Captura atualizada.':'Ideia guardada. Organize quando quiser.');};
  A.forms.task=data=>{const id=data.get('id'),existing=S().tasks.find(t=>t.id===id),origin=data.get('origin');if(origin&&!existing){const capture=S().captures.find(c=>c.id===origin);if(capture?.converted)return A.notify('Esta captura já tem um destino.');}const values={title:String(data.get('title')).trim(),description:String(data.get('description')||'').trim(),project:data.get('project'),category:data.get('category'),status:data.get('status'),priority:data.get('priority'),due:data.get('due'),estimate:Number(data.get('estimate'))||25,noteId:data.get('noteId'),origin:origin||undefined,relatedEvent:data.get('relatedEvent')||undefined};if(!values.title)return;if(existing)Object.assign(existing,values);else{const newId=A.uid('t');S().tasks.unshift({id:newId,...values});if(origin){const c=S().captures.find(c=>c.id===origin);if(c)Object.assign(c,{converted:true,taskId:newId});}}A.closeDialog();A.persist(existing?'Tarefa atualizada.':'Tarefa criada.');};
  A.forms.note=data=>{const id=data.get('id'),existing=S().notes.find(n=>n.id===id),title=String(data.get('title')).trim(),origin=data.get('origin');if(!title)return;if(S().notes.some(n=>!n.deleted&&n.id!==id&&n.title.toLocaleLowerCase()===title.toLocaleLowerCase()))return A.notify('Já existe uma página com esse título. Escolha outro nome.');if(origin&&!existing&&S().captures.find(c=>c.id===origin)?.converted)return A.notify('Esta captura já foi organizada.');if(existing&&existing.title!==title){S().notes.forEach(n=>{n.body=n.body.split('[['+existing.title+']]').join('[['+title+']]');});}const values={title,body:String(data.get('body')||''),notebook:data.get('notebook'),project:data.get('project'),updated:A.TODAY,origin:origin||undefined,relatedEvent:data.get('relatedEvent')||undefined};let newId=id;if(existing)Object.assign(existing,values);else{newId=A.uid('n');S().notes.unshift({id:newId,...values});}if(origin){const c=S().captures.find(c=>c.id===origin);if(c)Object.assign(c,{converted:true,noteId:newId});}if(values.relatedEvent){const ev=S().events.find(e=>e.id===values.relatedEvent);if(ev)ev.noteId=newId;}A.save();A.log('Página salva',title);A.closeDialog();A.go('conhecimento',newId);A.notify('Página salva e conexões atualizadas.');};
  A.forms.project=data=>{const id=data.get('id'),p=S().projects.find(p=>p.id===id),values={title:String(data.get('title')).trim(),description:String(data.get('description')).trim(),deadline:data.get('deadline'),status:data.get('status')};if(!values.title)return;if(p)Object.assign(p,values);else S().projects.push({id:A.uid('p'),color:'blue',...values});A.closeDialog();A.persist('Projeto salvo.');};
  A.forms.notebook=data=>{const title=String(data.get('title')).trim();if(!title)return;if(S().notebooks.includes(title))return A.notify('Já existe um caderno com esse nome.');S().notebooks.push(title);A.ui.noteFilter=title;A.closeDialog();A.persist('Caderno criado.');};
  Object.assign(A.actions,{
    'close-dialog':()=>A.closeDialog(), 'toggle-menu':()=>A.setMobileNav(!A.ui.mobileNav), 'toggle-sidebar':()=>A.toggleSidebar(),
    'toggle-theme':()=>A.setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'),
    'quick-capture':()=>quickCapture(), 'edit-capture':el=>quickCapture(el.dataset.id),
    'capture-filter':el=>{A.ui.captureFilter=el.dataset.value;A.render();},
    'convert-capture':el=>{const c=S().captures.find(c=>c.id===el.dataset.id);if(!c||c.converted)return;A.taskDialog(null,{title:c.title,description:c.body,origin:c.id});},
    'promote-capture':el=>{const c=S().captures.find(c=>c.id===el.dataset.id);if(!c||c.converted)return;A.noteDialog(null,{title:c.title,body:c.body||c.title,origin:c.id});},
    'view-origin':el=>{const c=S().captures.find(c=>c.id===el.dataset.id);if(c)A.openDialog('Captura de origem',`<div class="origin-content"><span class="pill">Origem preservada</span><h3>${E(c.title)}</h3><p>${E(c.body)}</p><small class="muted">Capturada em ${A.dateLabel(c.created)}. O conteúdo organizado é editado no destino.</small></div>`);},
    'new-task':()=>A.taskDialog(), 'open-task':el=>A.taskDialog(el.dataset.id),
    'toggle-task':el=>{const t=S().tasks.find(t=>t.id===el.dataset.id);if(!t||t.deleted)return;t.status=t.status==='done'?'todo':'done';A.persist(t.status==='done'?'Tarefa concluída. Um passo a menos.':'Tarefa reaberta.');},
    'task-filter':el=>{A.ui.taskFilter=el.dataset.value;A.render();},
    'delete-task':el=>{const t=S().tasks.find(t=>t.id===el.dataset.id);if(t)t.deleted=true;A.closeDialog();A.persist('Tarefa movida para a lixeira. Você pode restaurá-la.');},
    'restore-task':el=>{const t=S().tasks.find(t=>t.id===el.dataset.id);if(t)t.deleted=false;A.closeDialog();A.persist('Tarefa restaurada.');},
    'home-habit':el=>{if(A.lifeToggleHabit)A.lifeToggleHabit(el.dataset.id);else{const h=S().habits.find(h=>h.id===el.dataset.id);if(!h)return;h.checked=h.checked.includes(A.TODAY)?h.checked.filter(d=>d!==A.TODAY):[...h.checked,A.TODAY];A.persist('Hábito atualizado.');}},
    'home-transaction':()=>{if(A.actions['life-transaction-new'])A.actions['life-transaction-new']();else{A.go('financeiro');setTimeout(()=>document.querySelector('[data-action="life-new-transaction"]')?.click(),0);}},
    'home-calendar-date':el=>{A.ui.calendarDate=el.dataset.date;A.ui.calendarView='day';A.go('calendario');},
    'home-event':el=>{if(A.actions['cal-event'])A.actions['cal-event'](el);else{A.go('calendario');setTimeout(()=>{const target=document.querySelector(`[data-id="${el.dataset.id}"]`);if(target)target.click();},0);}},
    'new-note':()=>A.noteDialog(), 'edit-note':el=>A.noteDialog(el.dataset.id),
    'notebook-filter':el=>{A.ui.noteFilter=el.dataset.value;A.go('conhecimento');},
    'new-notebook':()=>A.openDialog('Novo caderno',`<form data-form="notebook"><label class="field">Nome do caderno<input name="title" required maxlength="60" autofocus placeholder="Ex.: Leituras"></label><div class="dialog-actions"><button class="button primary" type="submit">Criar caderno</button></div></form>`),
    'unresolved-note':el=>A.noteDialog(null,{title:el.dataset.title}),
    'delete-note':el=>A.openDialog('Excluir página',`<p>A página vai sair do Conhecimento. As tarefas e os projetos relacionados serão preservados.</p><div class="dialog-actions"><button class="button" data-action="close-dialog">Cancelar</button><button class="button danger" data-action="confirm-delete-note" data-id="${E(el.dataset.id)}">Excluir página</button></div>`),
    'confirm-delete-note':el=>{const n=S().notes.find(n=>n.id===el.dataset.id);if(n){n.deleted=true;S().events.forEach(event=>{if(event.noteId===n.id)delete event.noteId;});S().tasks.forEach(task=>{if(task.noteId===n.id)delete task.noteId;});}A.save();A.go('conhecimento');A.notify('Página excluída. Tarefas e compromissos preservados.');},
    'new-project':()=>projectDialog(), 'edit-project':el=>projectDialog(el.dataset.id), 'project-task':el=>A.taskDialog(null,{project:el.dataset.id}),
    'confirm-reset':()=>{A.state=structuredClone(A.seed);A.ui.taskFilter='all';A.ui.noteFilter='Todos';A.save();A.go('inicio');A.notify('Demonstração restaurada.');},
    'search':()=>openSearch(), 'close-search':()=>document.querySelector('#search-dialog').close(),
    'search-result':el=>{document.querySelector('#search-dialog').close();const type=el.dataset.type,id=el.dataset.id;if(type==='event')A.actions['home-event'](el);else if(type==='task')A.taskDialog(id);else if(type==='capture'){const c=S().captures.find(c=>c.id===id);if(c?.converted)A.go(c.taskId?'tarefas':'conhecimento',c.taskId||c.noteId);else openSearchRecord('capturar','edit-capture',id);}else if(type==='habit')openSearchRecord('habitos','life-habit-edit',id);else if(type==='financeiro'&&id)openSearchRecord('financeiro','life-transaction-edit',id);else A.go(type,id);},
    'task-related-note':el=>{const id=el.closest('form').elements.noteId.value;if(S().notes.some(n=>n.id===id&&!n.deleted))A.openNote(id);else A.notify('Escolha uma nota disponível para abrir.');},
    'task-related-event':el=>A.actions['cal-event']?.(el)
  });
  function openSearchRecord(routeName,action,id){if(A.ui.route===routeName){A.actions[action]?.({dataset:{id}});return;}A.ui.pendingSearchAction={route:routeName,action,id};A.go(routeName);}
  function openSearch(){const d=document.querySelector('#search-dialog');d.innerHTML=`<div class="search-input-wrap">${I('search',22)}<input id="global-search" placeholder="O que você quer reencontrar?" aria-label="Buscar em todo o espaço" autocomplete="off"><button class="icon-button" data-action="close-search" aria-label="Fechar busca">${I('x',19)}</button></div><div id="search-results"></div><footer class="search-footer"><span>Busque tarefas, páginas, ideias, hábitos e lançamentos · ↑ ↓ navegar · Enter abrir</span><kbd>Esc</kbd></footer>`;d.showModal();d.querySelector('input').focus();renderSearch('');}
  function renderSearch(query){
    const q=query.trim().toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'');let items=[];
    if(q)items=[
      ...S().tasks.filter(t=>!t.deleted&&t.status!=='archived').map(t=>({id:t.id,title:t.title,detail:projectName(t.project),type:'task',label:'Tarefa',icon:'tasks'})),
      ...S().notes.filter(n=>!n.deleted&&!n.archived).map(n=>({id:n.id,title:n.title,detail:n.notebook,type:'conhecimento',label:'Página',icon:'file-text'})),
      ...S().captures.filter(c=>!c.converted&&!c.deleted&&!c.archived).map(c=>({id:c.id,title:c.title,detail:'Caixa de entrada',type:'capture',label:'Captura',icon:'capture'})),
      ...S().events.filter(event=>S().calendarSources[event.source]!==false).map(event=>({id:event.id,title:event.title,detail:A.dateLabel(event.date),type:'event',label:'Compromisso',icon:'calendar'})),
      ...S().projects.filter(p=>!p.deleted&&!p.archived).map(p=>({id:p.id,title:p.title,detail:'Projeto pessoal',type:'projetos',label:'Projeto',icon:'folder'})),
      ...S().habits.filter(h=>!h.deleted&&!h.archived).map(h=>({id:h.id,title:h.title,detail:A.lifeHabitSchedule?.(h)||'Sua rotina',type:'habit',label:'Hábito',icon:'habit'})),
      ...(S().settings.hideAmounts?[]:S().transactions.filter(t=>!t.deleted&&t.status!=='cancelled').map(t=>({id:t.id,title:t.title,detail:A.money(t.amount),type:'financeiro',label:'Lançamento',icon:'wallet'})))
    ].filter(x=>(x.title+' '+x.detail).toLocaleLowerCase('pt-BR').normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(q)).slice(0,12);
    document.querySelector('#search-results').innerHTML=q?`<p class="search-label" role="status">${items.length} resultados</p>${items.map(x=>`<button class="search-result" data-action="search-result" data-type="${x.type}" data-id="${E(x.id)}">${I(x.icon,21)}<span><strong>${E(x.title)}</strong><small>${E(x.detail)}</small></span><span class="pill">${x.label}</span>${I('arrow-up-right',16)}</button>`).join('')||empty('Nada encontrado por enquanto','Tente outra palavra ou busque pelo nome do projeto.')}${S().settings.hideAmounts?'<p class="search-label">Lançamentos ficam fora da busca enquanto os valores estão ocultos.</p>':''}`:`<p class="search-label">Ir para</p>${nav.slice(0,7).map(([key,icon,label])=>`<button class="search-result" data-action="search-result" data-type="${key}">${I(icon,21)}<strong>${label}</strong>${I('arrow-up-right',16)}</button>`).join('')}`;
  }
  document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const fn=A.actions[el.dataset.action];if(fn){if(el.tagName!=='INPUT')event.preventDefault();fn(el,event);}});
  document.addEventListener('submit',event=>{const form=event.target.closest('form[data-form]');if(!form)return;event.preventDefault();if(form.reportValidity())A.forms[form.dataset.form]?.(new FormData(form),form);});
  document.addEventListener('input',event=>{const el=event.target;if(el.id==='global-search')renderSearch(el.value);if(el.dataset.input==='task-search'){const cursor=el.selectionStart;A.ui.taskQuery=el.value;A.render();const input=document.querySelector('[data-input="task-search"]');input.focus();try{input.setSelectionRange(cursor,cursor);}catch(e){}}});
  document.addEventListener('change',event=>{const el=event.target;if(el.dataset.change==='task-project')A.ui.taskProject=el.value;else if(el.dataset.change==='task-sort')A.ui.taskSort=el.value;else return;A.render();});
  document.addEventListener('keydown',event=>{
    if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();if(A.ui.route!=='onboarding'&&!document.querySelector('#search-dialog').open)openSearch();return;}
    if(document.querySelector('#search-dialog').open){
      const results=[...document.querySelectorAll('#search-results .search-result')],current=results.indexOf(document.activeElement);
      if(results.length&&(event.key==='ArrowDown'||event.key==='ArrowUp')){event.preventDefault();results[event.key==='ArrowDown'?(current+1)%results.length:(current<=0?results.length-1:current-1)].focus();return;}
      if(results.length&&event.key==='Enter'&&(current>=0||document.activeElement.id==='global-search')){event.preventDefault();results[Math.max(0,current)].click();return;}
    }
    if(event.key==='Escape'&&A.ui.mobileNav){event.preventDefault();A.setMobileNav(false);}
  });
  document.querySelector('#detail-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget){const b=e.currentTarget.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)A.closeDialog();}});
  document.querySelector('#detail-dialog').addEventListener('close',()=>{if(A._returnFocus?.isConnected)A._returnFocus.focus();});
  matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(A.ui.theme==='system')A.setTheme('system');});
  function route(){if(location.hash==='#main'){if(!document.querySelector('#main'))A.render();document.querySelector('#main')?.focus();return;}const parts=location.hash.replace(/^#\/?/,'').split('/');A.ui.route=names[parts[0]]?parts[0]:'inicio';A.ui.id=parts[1]?decodeURIComponent(parts[1]):null;A.ui.mobileNav=false;A.closeDialog();document.querySelector('#search-dialog').close();if(A.lifeLockVault)A.lifeLockVault(false);A.render();window.scrollTo(0,0);if(document.documentElement.dataset.input==='keyboard')document.querySelector('#main')?.focus({preventScroll:true});if(A.ui.route==='tarefas'&&A.ui.id)A.taskDialog(A.ui.id);if(A.ui.route==='calendario'&&A.ui.id)A.actions['cal-event']?.({dataset:{id:A.ui.id}});const pending=A.ui.pendingSearchAction;delete A.ui.pendingSearchAction;if(pending?.route===A.ui.route)A.actions[pending.action]?.({dataset:{id:pending.id}});}
  A.onboarding.init();window.addEventListener('hashchange',route);route();
})();
